#include "BackupController.h"
#include "../services/BusinessSupport.h"
#include "../services/DocumentAccess.h"
#include <regex>
namespace erp {
namespace {
void admin(const drogon::HttpRequestPtr &req){auto roles=req->getAttributes()->get<std::string>("roles");business::require((","+roles+",").find(",admin,")!=std::string::npos,"仅管理员可维护备份配置",ErrorCode::FORBIDDEN);}
Json::Value defaults(){Json::Value v;v["enabled"]=false;v["host"]="";v["port"]=22;v["username"]="";v["remote_dir"]="/srv/erp-backups";v["ssh_key_path"]="/opt/erp/keys/backup_ed25519";v["local_dir"]="/opt/erp/backups";v["time"]="03:00";v["keep_count"]=14;return v;}
Json::Value clean(const Json::Value &input){
 using business::require;require(input.isObject()&&input["enabled"].isBool(),"配置格式错误");auto v=defaults();for(auto key:{"host","username","remote_dir","ssh_key_path","local_dir","time"}){require(input[key].isString(),"配置字段格式错误");v[key]=input[key];}require(input["port"].isIntegral()&&input["keep_count"].isIntegral(),"端口和保留份数须为整数");v["enabled"]=input["enabled"];v["port"]=input["port"];v["keep_count"]=input["keep_count"];require(v["port"].asInt()>=1&&v["port"].asInt()<=65535&&v["keep_count"].asInt()>=1&&v["keep_count"].asInt()<=365,"端口或保留份数超出范围");require(std::regex_match(v["time"].asString(),std::regex("([01][0-9]|2[0-3]):[0-5][0-9]")),"请使用HH:mm时间");
 auto host=v["host"].asString(),user=v["username"].asString();require((host.empty()&&!v["enabled"].asBool())||std::regex_match(host,std::regex("[A-Za-z0-9][A-Za-z0-9.-]{0,252}")),"服务器地址仅支持IPv4或主机名");require((user.empty()&&!v["enabled"].asBool())||std::regex_match(user,std::regex("[a-z_][a-z0-9_-]{0,31}")),"登录用户名格式错误");for(auto key:{"remote_dir","ssh_key_path","local_dir"}){auto path=v[key].asString();require(path.size()<=240&&std::regex_match(path,std::regex("/[A-Za-z0-9_./-]+"))&&path.find("..") == std::string::npos&&path!="/","路径须为非根绝对路径，只含字母、数字、下划线、点、短横线和斜杠");}return v;
}
}
void BackupController::get(const drogon::HttpRequestPtr &req,std::function<void(const drogon::HttpResponsePtr &)> &&cb){
 try{admin(req);auto db=drogon::app().getDbClient();Json::Value data;data["settings"]=defaults();auto settings=db->execSqlSync("SELECT setting_value FROM operational_settings WHERE setting_key='backup'");if(!settings.empty()){Json::Reader r;business::require(r.parse(settings[0]["setting_value"].as<std::string>(),data["settings"]),"配置无法读取");}auto agent=db->execSqlSync("SELECT last_seen_at,last_seen_at>=DATE_SUB(NOW(),INTERVAL 15 MINUTE) AS online FROM backup_agent WHERE id=1");data["agent_online"]=!agent.empty()&&agent[0]["online"].as<int>()!=0;data["agent_last_seen"]=agent.empty()?"":agent[0]["last_seen_at"].as<std::string>();auto jobs=db->execSqlSync("SELECT b.id,b.status AS job_state,b.requested_by,b.created_at,b.started_at,b.completed_at,b.details,COALESCE(NULLIF(u.real_name,''),u.username) AS requested_by_name FROM backup_requests b LEFT JOIN user_directory u ON u.id=b.requested_by ORDER BY b.id DESC LIMIT 30");data["jobs"]=Json::Value(Json::arrayValue);for(auto row:jobs){auto value=business::rowJson(jobs,row);value["status"]=value["job_state"];value.removeMember("job_state");if(!row["details"].isNull()){Json::Reader r;r.parse(row["details"].as<std::string>(),value["details"]);}data["jobs"].append(value);}cb(ApiResponse::ok("备份配置及执行状态",data));}
 catch(const business::Error &e){cb(ApiResponse::error(e.code,e.what()));}catch(const std::exception &){cb(ApiResponse::error(ErrorCode::INTERNAL_ERROR,"备份配置读取失败"));}
}
void BackupController::save(const drogon::HttpRequestPtr &req,std::function<void(const drogon::HttpResponsePtr &)> &&cb){
 try{admin(req);auto json=req->getJsonObject();business::require(bool(json),"请提交配置");auto settings=clean(*json);auto user=std::stoll(req->getAttributes()->get<std::string>("user_id"));business::transaction([cb](int code,const std::string &msg,const Json::Value &data){cb(code==ErrorCode::OK?ApiResponse::ok(msg,data):ApiResponse::error(code,msg));},[=](const business::Tx &tx){Json::StreamWriterBuilder writer;tx->execSqlSync("INSERT INTO operational_settings(setting_key,setting_value,updated_by) VALUES('backup',?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)",Json::writeString(writer,settings),user);tx->execSqlSync("UPDATE backup_requests SET status='failed',completed_at=NOW(),details=JSON_OBJECT('message','备份配置已变更，原排队任务已取消') WHERE status='queued'");business::event(tx,"operational_settings",0,"backup_settings",user,-1,1);business::Outcome out;out.message="配置已保存，实际执行取决于宿主机备份任务是否在线";return out;});}catch(const business::Error &e){cb(ApiResponse::error(e.code,e.what()));}catch(const std::exception &){cb(ApiResponse::error(ErrorCode::BAD_REQUEST,"配置格式错误"));}
}
void BackupController::request(const drogon::HttpRequestPtr &req,std::function<void(const drogon::HttpResponsePtr &)> &&cb){
 try{admin(req);auto user=std::stoll(req->getAttributes()->get<std::string>("user_id"));business::transaction([cb](int code,const std::string &msg,const Json::Value &data){cb(code==ErrorCode::OK?ApiResponse::ok(msg,data):ApiResponse::error(code,msg));},[=](const business::Tx &tx){tx->execSqlSync("SELECT setting_key FROM operational_settings WHERE setting_key='backup' FOR UPDATE");auto settings=tx->execSqlSync("SELECT setting_value FROM operational_settings WHERE setting_key='backup'");business::require(!settings.empty(),"请先配置备份");Json::Value value;Json::Reader r;business::require(r.parse(settings[0]["setting_value"].as<std::string>(),value),"配置无法读取");clean(value);business::require(value["enabled"].asBool(),"请先启用备份");business::require(tx->execSqlSync("SELECT id FROM backup_requests WHERE status IN ('queued','running') LIMIT 1 FOR UPDATE").empty(),"已有待执行或进行中的备份",ErrorCode::CONFLICT);auto job=tx->execSqlSync("INSERT INTO backup_requests(requested_by) VALUES(?)",user);business::event(tx,"backup_requests",job.insertId(),"request",user,-1,0);business::Outcome out;out.data["job_id"]=Json::UInt64(job.insertId());out.message="已排队，等待宿主机任务执行，不代表备份成功";return out;},business::requestIdentity(req));}catch(const business::Error &e){cb(ApiResponse::error(e.code,e.what()));}catch(const std::exception &){cb(ApiResponse::error(ErrorCode::BAD_REQUEST,"备份请求失败"));}
}
}
